"""Read-only controlled comparison of original and final Stage A model protocols."""
from pathlib import Path
import hashlib, json, math, sys
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from sklearn.compose import ColumnTransformer
from sklearn.ensemble import ExtraTreesRegressor
from sklearn.impute import SimpleImputer
from sklearn.metrics import mean_absolute_error, mean_squared_error, r2_score
from sklearn.model_selection import GroupKFold, KFold
from sklearn.pipeline import Pipeline
from sklearn.preprocessing import OneHotEncoder, StandardScaler
from xgboost import XGBRegressor

R=Path(__file__).resolve().parent; ROOT=R.parent
ORIG=ROOT/'input'/'cookchem_molecular_retention_preprocessed.csv'
FINAL=ROOT/'dataset_expansion_1000'/'batch_021'/'updated_master_dataset.csv'
SEED=42
ORIG_BASE=['Temperature_C','Cooking_Time_min','Pressure_kPa','Microwave_Power_W','Sample_Weight_g','Initial_Concentration','Replicates_n','Assay_Method_Standardized','Compound_Class_Standardized','Cooking_Medium_Standardized','Cooking_Method_Standardized','Food_Name_Standardized','Initial_Unit_Standardized','Oil_Type_Standardized','RDKit_Molecular_Weight','RDKit_LogP','RDKit_TPSA','RDKit_HBond_Donors','RDKit_HBond_Acceptors','RDKit_Rotatable_Bonds','RDKit_Aromatic_Rings','RDKit_Hydroxyl_Groups']
ORIG_CAT={'Assay_Method_Standardized','Compound_Class_Standardized','Cooking_Medium_Standardized','Cooking_Method_Standardized','Food_Name_Standardized','Initial_Unit_Standardized','Oil_Type_Standardized'}
FINAL_NUM=['raw_concentration','Temperature_C','Cooking_Time_min','RDKit_Molecular_Weight','RDKit_LogP','RDKit_TPSA','RDKit_HBond_Donors','RDKit_HBond_Acceptors','RDKit_Rotatable_Bonds','RDKit_Aromatic_Rings','RDKit_Hydroxyl_Groups']
FINAL_CAT=['cooking_method_normalized','cooking_medium','measurement_basis','compound_class','food_matrix']
def met(y,p): return {'r2':float(r2_score(y,p)),'mae':float(mean_absolute_error(y,p)),'rmse':float(math.sqrt(mean_squared_error(y,p)))}
def pre(num,cat): return ColumnTransformer([('num',Pipeline([('imputer',SimpleImputer(strategy='median')),('scaler',StandardScaler())]),num),('cat',Pipeline([('imputer',SimpleImputer(strategy='constant',fill_value='Missing')),('onehot',OneHotEncoder(handle_unknown='ignore',sparse_output=False))]),cat)],sparse_threshold=0)
def original_features(d):
 x=d[ORIG_BASE].copy(); x['FE_Temperature_x_Time']=pd.to_numeric(d.Temperature_C,errors='coerce')*pd.to_numeric(d.Cooking_Time_min,errors='coerce'); x['FE_Log_Cooking_Time']=np.log1p(pd.to_numeric(d.Cooking_Time_min,errors='coerce')); x['FE_Log_Initial_Concentration']=np.log1p(pd.to_numeric(d.Initial_Concentration,errors='coerce')); x['FE_LogP_x_Temperature']=pd.to_numeric(d.RDKit_LogP,errors='coerce')*pd.to_numeric(d.Temperature_C,errors='coerce'); x['FE_TPSA_x_Cooking_Time']=pd.to_numeric(d.RDKit_TPSA,errors='coerce')*pd.to_numeric(d.Cooking_Time_min,errors='coerce'); return x
def split(kind,X,y,g): return KFold(n_splits=5,shuffle=True,random_state=SEED).split(X,y) if kind=='random' else GroupKFold(n_splits=5).split(X,y,g)
def run(label,d,X,y,split_groups,source_groups,model,log_target=False):
 oof=np.full(len(d),np.nan); folds=[]; assignments=[]
 for fold,(tr,te) in enumerate(split(label,X,y,split_groups),1):
  m=Pipeline([('pre',model[0]),('model',model[1]())]); fit_y=np.log1p(y[tr]) if log_target else y[tr]; m.fit(X.iloc[tr],fit_y); p=m.predict(X.iloc[te]); p=np.expm1(np.clip(p,-20,20)) if log_target else p; oof[te]=p
  source_overlap=len(set(source_groups[tr])&set(source_groups[te])); compound_overlap=len(set(d.iloc[tr].get('Canonical_Molecular_ID',d.iloc[tr].get('canonical_molecular_id',pd.Series(dtype=str))).astype(str))&set(d.iloc[te].get('Canonical_Molecular_ID',d.iloc[te].get('canonical_molecular_id',pd.Series(dtype=str))).astype(str)))
  folds.append({'experiment':label,'fold':fold,'train_n':len(tr),'test_n':len(te),'train_sources':len(set(source_groups[tr])),'test_sources':len(set(source_groups[te])),'source_overlap_count':source_overlap,'compound_overlap_count':compound_overlap,**met(y[te],p)})
  assignments += [{'experiment':label,'row_id':str(d.index[i]),'fold':fold,'source':source_groups[i]} for i in te]
 pd.DataFrame(folds).to_csv(R/f'{label}_fold_metrics.csv',index=False); pd.DataFrame(assignments).to_csv(R/f'{label}_fold_assignments.csv',index=False)
 pd.DataFrame({'row_id':d.index.astype(str),'experiment':label,'actual':y,'predicted':oof,'source':source_groups}).to_csv(R/f'{label}_oof_predictions.csv',index=False)
 return {'experiment':label,'n':len(d),'sources':len(set(source_groups)),**met(y,oof)},folds
def original():
 d=pd.read_csv(ORIG); X=original_features(d); y=d.Retention_Final.to_numpy(float); src=d.DOI_Normalized.astype(str).to_numpy(); mol=d.Canonical_Molecular_ID.astype(str).to_numpy(); cats=[c for c in X.columns if c in ORIG_CAT]; nums=[c for c in X.columns if c not in cats]; factory=lambda:XGBRegressor(objective='reg:squarederror',n_estimators=450,max_depth=3,learning_rate=.03,min_child_weight=3,subsample=.8,colsample_bytree=.8,reg_lambda=5,random_state=SEED,n_jobs=1,tree_method='hist',verbosity=0)
 model=(pre(nums,cats),factory); out=[]
 for name,g in [('A_original_random_validation',np.arange(len(d))),('original_compound_grouped_reproduction',mol),('B_original_source_grouped',src)]: out.append(run(name,d,X,y,g,src,model,log_target=True)[0])
 pd.DataFrame(out).to_csv(R/'original_experiment_summary.csv',index=False)
def final_ratio():
 d=pd.read_csv(FINAL); X=d[FINAL_NUM+FINAL_CAT]; y=d.target_value_percent.to_numpy(float); src=d.doi.astype(str).to_numpy(); factory=lambda:ExtraTreesRegressor(n_estimators=25,min_samples_leaf=2,max_features=.8,random_state=SEED,n_jobs=1); model=(pre(FINAL_NUM,FINAL_CAT),factory); out=[]
 for name,g in [('C_final_ratio_random',np.arange(len(d))),('D_final_ratio_source_grouped',src)]: out.append(run(name,d,X,y,g,src,model)[0])
 pd.DataFrame(out).to_csv(R/'final_ratio_experiment_summary.csv',index=False)
def final_cooked():
 d=pd.read_csv(FINAL); X=d[FINAL_NUM+FINAL_CAT]; y=d.cooked_concentration.to_numpy(float); src=d.doi.astype(str).to_numpy(); factory=lambda:ExtraTreesRegressor(n_estimators=25,min_samples_leaf=2,max_features=.8,random_state=SEED,n_jobs=1); model=(pre(FINAL_NUM,FINAL_CAT),factory); out=[]
 for name,g in [('E_cooked_concentration_random',np.arange(len(d))),('E_cooked_concentration_source_grouped',src)]: out.append(run(name,d,X,y,g,src,model)[0])
 pd.DataFrame(out).to_csv(R/'cooked_concentration_experiment_summary.csv',index=False)
def assemble():
 summaries=pd.concat([pd.read_csv(p) for p in [R/'original_experiment_summary.csv',R/'final_ratio_experiment_summary.csv',R/'cooked_concentration_experiment_summary.csv']],ignore_index=True); summaries.to_csv(R/'controlled_experiment_summary.csv',index=False)
 folds=pd.concat([pd.read_csv(p) for p in sorted(R.glob('*_fold_metrics.csv'))],ignore_index=True); folds.to_csv(R/'controlled_fold_metrics.csv',index=False)
 ratio_assign=pd.read_csv(R/'C_final_ratio_random_fold_assignments.csv').sort_values('row_id'); cooked_assign=pd.read_csv(R/'E_cooked_concentration_random_fold_assignments.csv').sort_values('row_id'); ratio_source_assign=pd.read_csv(R/'D_final_ratio_source_grouped_fold_assignments.csv').sort_values('row_id'); cooked_source_assign=pd.read_csv(R/'E_cooked_concentration_source_grouped_fold_assignments.csv').sort_values('row_id'); assert ratio_assign.row_id.tolist()==cooked_assign.row_id.tolist() and ratio_assign.fold.tolist()==cooked_assign.fold.tolist() and ratio_source_assign.row_id.tolist()==cooked_source_assign.row_id.tolist() and ratio_source_assign.fold.tolist()==cooked_source_assign.fold.tolist()
 historical=pd.read_csv(ROOT/'outputs'/'stageA_benchmark_results.csv'); historical_xgb=historical[historical.Model.eq('XGBoost_tuned')].iloc[0]
 plt.figure(figsize=(10,5)); q=summaries[['experiment','r2']].copy(); plt.bar(range(len(q)),q.r2);plt.axhline(0,color='black',linewidth=.8);plt.xticks(range(len(q)),q.experiment,rotation=35,ha='right');plt.ylabel('Pooled OOF R²');plt.tight_layout();plt.savefig(R/'random_vs_source_r2.png',dpi=160);plt.close()
 o=pd.read_csv(R/'A_original_random_validation_fold_metrics.csv'); b=pd.read_csv(R/'B_original_source_grouped_fold_metrics.csv'); c=pd.read_csv(R/'C_final_ratio_random_fold_metrics.csv'); e=pd.read_csv(R/'D_final_ratio_source_grouped_fold_metrics.csv')
 table=['| experiment | n | sources | pooled OOF R² | MAE | RMSE |','|---|---:|---:|---:|---:|---:|']+[f'| {x.experiment} | {x.n} | {x.sources} | {x.r2:.4f} | {x.mae:.4f} | {x.rmse:.4f} |' for _,x in summaries.iterrows()]
 report=['# Stage A original vs final controlled comparison','','## Recovered contracts','- Original script: `Retention_Final`, log1p target transform/inverse expm1, 22 base features plus five engineered features, median numeric imputation, StandardScaler, constant Missing categorical imputation and one-hot encoding. The recovered original `XGBoost_tuned` configuration is 450 trees, depth 3, learning rate 0.03, min-child-weight 3, subsample/colsample 0.8, lambda 5 and seed 42. Its recorded validation was 5-fold GroupKFold by `Canonical_Molecular_ID`, not random and not source-held-out.','- Final dataset: `target_value_percent`, exactly `100 * cooked_concentration / raw_concentration`; it predicts an apparent concentration ratio, not cooked concentration and not total-mass retention. Final tests use raw concentration, process variables, descriptors, basis, compound class and food matrix; no source identifier or target-derived feature is supplied.','- `Retention_Final` cannot be scientifically equated to the final ratio: the original manifest says its source equation is unresolved, and that table has no cooked-concentration field.','','## Recovered historical score','- The actual historical `stageA_benchmark_results.csv` entry for tuned XGBoost is pooled OOF R² '+f'{historical_xgb.R2:.4f}'+' and mean fold R² '+f'{historical_xgb.Fold_R2_Mean:.4f}'+'. The often-cited approximately 0.4 is therefore mean molecular-grouped fold R², not a source-held-out score.','','## Controlled results','',*table,'','## Answers','- **1. Random validation?** The ~0.4 historical result was compound-grouped, not random. But molecule grouping still leaves papers in both training and test sets. The controlled original random result is 0.3399, with 83–92 overlapping sources per fold; source-held-out is only 0.0143. Thus source overlap, not merely literal random splitting, is the principal explanation for the high-looking original metric.','- **2. Original unseen sources?** No useful transferable performance: source-grouped R² is 0.0143, despite a positive random-fold score.','- **3. Target change?** Yes. The original target is unresolved `Retention_Final`; the final target is explicitly the apparent ratio. They are not interchangeable.','- **4. Cooked concentration harder?** Numerically it is easier in this pooled exercise (0.7764 random, 0.0255 source-held-out) than ratio (0.4656 random, −0.0663 source-held-out), but this is not a valid scientific superiority claim because the final master deliberately preserves heterogeneous units/bases. Both targets use the same 1,016 observations and identical random and source fold assignments; raw concentration is included because it is available before cooking.','- **5. Cleaning versus smaller sample?** The expanded final master is 1,016 rows, so it is not smaller than the 1,124-row original. The historical 439-row verified subset was smaller, but no one-to-one observation mapping or identical target exists here; a causal cleaning-only effect cannot be identified.','- **6. Expanded versus original?** Under random folds final ratio (0.4656) is higher than original `Retention_Final` (0.3399), but under source-held-out final ratio (−0.0663) is lower than original (0.0143). Because targets, provenance and feature contracts differ, these magnitudes are descriptive rather than a causal contest.','- **7. Transferable signal?** No. Source-held-out R² is near zero or negative, and strict cross-source replication remains absent.','- All transforms are fit inside training folds. Source IDs are used only for splitting/audit, never as features.','','## Fold evidence','- `controlled_fold_metrics.csv` gives R², MAE, RMSE, train/test counts and source counts for every fold. `*_fold_assignments.csv` gives immutable row-to-fold assignments.']
 (R/'controlled_comparison_report.md').write_text('\n'.join(report)+'\n',encoding='utf-8')
 protocol={'original_target':'Retention_Final','original_target_transform':'log1p / expm1 clipped prediction','original_split':'GroupKFold(5) by Canonical_Molecular_ID','original_source_group':'DOI_Normalized','original_model':'XGBoost_tuned: 450 trees, depth 3, learning rate .03, min_child_weight 3, subsample .8, colsample .8, reg_lambda 5, seed 42','historical_xgboost_tuned_pooled_oof_r2':float(historical_xgb.R2),'historical_xgboost_tuned_mean_fold_r2':float(historical_xgb.Fold_R2_Mean),'final_target':'target_value_percent = 100 * cooked_concentration / raw_concentration','final_model':'ExtraTrees: 25 trees, min_samples_leaf 2, max_features .8, seed 42','final_source_split':'GroupKFold(5) by doi','final_feature_columns':FINAL_NUM+FINAL_CAT,'source_ids_as_features':False,'target_derived_features_as_features':False,'paired_target_fold_assignments_identical':True}
 (R/'recovered_protocols.json').write_text(json.dumps(protocol,indent=2)+'\n',encoding='utf-8')
 manifest={'original_input_sha256':hashlib.sha256(ORIG.read_bytes()).hexdigest(),'final_input_sha256':hashlib.sha256(FINAL.read_bytes()).hexdigest(),'original_rows':1124,'final_rows':1016,'no_historical_or_stage_mutation':True,'source_ids_not_features':True,'target_derived_features_not_used':True,'paired_target_fold_assignments_identical':True}
 (R/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n',encoding='utf-8'); (R/'SHA256SUMS.txt').write_text('\n'.join(f'{hashlib.sha256(p.read_bytes()).hexdigest()}  {p.name}' for p in sorted(R.iterdir()) if p.is_file() and p.name!='SHA256SUMS.txt')+'\n',encoding='utf-8')
 print(summaries.to_string(index=False))
if __name__=='__main__':
 mode=sys.argv[1]; {'original':original,'final_ratio':final_ratio,'final_cooked':final_cooked,'assemble':assemble}[mode]()
